 var big=el('div','',null,box);big.style.cssText='font-size:56px;font-weight:800;text-align:center;font-family:var(--serif)';var r=row(box);r.innerHTML='<input type="text" style="width:200px" placeholder="Type the word" autocomplete="off">';var inp=r.querySelector('input');btn(r,'Check',chk,'pri');btn(r,'Show list',function(){m.set(A.join(', '))});var m=msg(box),sk=el('p','small','Streak: 0',box);
