 function chk(){var v=inp.value.trim().toLowerCase().replace(/\s/g,'');v=ALT[v]||v;if(!v){m.set('Type a word.',false);return}if(v===A[q].toLowerCase()){streak++;m.set('Correct: '+A[q]+'.',true)}else{streak=0;m.set(big.textContent+' is '+A[q]+'.',false)}sk.textContent='Streak: '+streak;setTimeout(nq,600)}
 inp.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();e.stopPropagation();chk()}});nq();
